<?php require_once __DIR__.'/../_bootstrap.php';admin();$d=body();required($d,['user_id','months']);$months=(int)$d['months'];if($months<1||$months>120)fail('Subscription duration must be between 1 and 120 months.');$q=db()->prepare("UPDATE users SET status='active',subscription_status='active',subscription_start_at=NOW(),subscription_end_at=DATE_ADD(NOW(), INTERVAL $months MONTH) WHERE id=? AND role='seller'");$q->execute([$d['user_id']]);if(!$q->rowCount())fail('Seller not found.',404);out(['success'=>true,'message'=>"Subscription set for $months month(s) starting today."]);
